    opacity: 0,
    side: THREE.DoubleSide
  });
  const frame = new THREE.Mesh(frameGeo, frameMat);
  frame.position.z = -0.008;
  mesh.add(frame);

  // Dark machined backing
  const backingGeo = new THREE.PlaneGeometry(W + 0.02, H + 0.02);
  const backingMat = new THREE.MeshStandardNodeMaterial({
