  // Entrance — rise-in
  mesh.position.y = baseY + 0.4;
  const entrance = gsap.timeline({ delay: 0.15 });
  entrance.to(mesh.position, { y: baseY, duration: 0.7, ease: 'power3.out' });
  timelines.push(entrance);

  // Hover — rise-in subtle
  const hoverIn = () => {
    const tl = gsap.timeline();
    tl.to(mesh.position, { y: baseY + 0.15, duration: 0.7, ease: 'power3.out' });
    timelines.push(tl);
  };

  const hoverOut = () => {
    const tl = gsap.timeline();
    tl.to(mesh.position, { y: baseY, duration: 0.5, ease: 'power3.out' });
    timelines.push(tl);
  };

  // Focus — accent edge
  const focusIn = () => {
    frame.visible = true;
    const tl = gsap.to(frameMat, { opacity: 1, duration: 0.3, ease: 'power2.out' });
    timelines.push(tl);
  };

  const focusOut = () => {
    const tl = gsap.timeline({
      onComplete: () => { if (frameMat.opacity < 0.05) frame.visible = false; }
    });
    tl.to(frameMat, { opacity: 0, duration: 0.3, ease: 'power2.out' });
    timelines.push(tl);
  };

  // Click — press-down + emit
  const press = () => {
    const tl = gsap.timeline();
    tl.to(mesh.scale, {
      x: scl[0] * 0.97, y: scl[1] * 0.97, z: scl[2] * 0.97,
      duration: 0.12, ease: 'back.out(2)'
    });
    tl.to(mesh.scale, {
      x: scl[0], y: scl[1], z: scl[2],
      duration: 0.2, ease: 'power3.out'
    });
    timelines.push(tl);
    if (ctx.emit) ctx.emit('hub-features.select', { id: config.id });
  };

  // Apply cinematic primitives
  if (Array.isArray(config.cinematicPrimitives)) {
    for (const primitive of config.cinematicPrimitives) {
      if (ctx.primitives && ctx.primitives[primitive.name]) {
        ctx.primitives[primitive.name](mesh, primitive.params);
      }
    }
  }

  mesh.userData.handlers = {
    pointerenter: hoverIn,
    pointerleave: hoverOut,
    click: press,
    focus: focusIn,
    blur: focusOut
  };

  mesh.userData.cleanup = () => {
    while (timelines.length) {
      const tl = timelines.pop();
      try { tl.kill(); } catch (e) {}
    }
    geometry.dispose();
    material.dispose();
    frameGeo.dispose();
    frameMat.dispose();
    backingGeo.dispose();
    backingMat.dispose();
  };

  return mesh;
}
